-- 为演示及首次使用补充可直接阅读的铜杆、拉丝设备知识。
-- 内容为通用运维参考，具体参数和操作边界仍以现场受控SOP、设备说明书为准。
INSERT INTO p2_knowledge_article
  (title, category, equipment_id, equipment_type, fault_phenomenon, content, steps, source_repair_order_id, created_at, updated_at)
SELECT x.title, x.category, e.equipment_id, NULL, x.fault_phenomenon, x.content, x.steps, NULL, NOW(3), NOW(3)
FROM dim_equipment e
JOIN (
  SELECT 'SMELT-FUR-01' equipment_code, '1#熔化炉设备与工艺作用' title, 'INTRODUCTION' category, NULL fault_phenomenon,
    '<h2>设备用途</h2><p>1#熔化炉承担铜板加热、熔化并向保温工序稳定供给铜液的任务，是车间1铜杆生产的首要热工设备。</p><h3>重点关注</h3><ul><li>炉膛上、中、下部温度及其温差</li><li>铜液液位、炉压和燃气流量</li><li>炉门、炉衬、燃烧器与热电偶状态</li></ul><blockquote>实际温度、压力和联锁边界必须以现场受控工艺卡及设备说明书为准。</blockquote>' content,
    JSON_ARRAY() steps
  UNION ALL SELECT 'HOLD-FUR-01', '保温炉的作用与运行关注点', 'INTRODUCTION', NULL,
    '<h2>设备用途</h2><p>保温炉用于承接熔化后的铜液，降低供液波动，为后续结晶牵引提供温度和液位相对稳定的铜液。</p><h3>运行关注点</h3><ul><li>铜液温度稳定性和保温时间</li><li>液位变化与上、下游节拍匹配</li><li>炉体密封、炉衬侵蚀及表面结渣</li></ul><p>温度波动异常时，应同时核对熔化炉出液、牵引负荷和测温元件，避免只调整单一设定值。</p>', JSON_ARRAY()
  UNION ALL SELECT 'CAST-01', '结晶牵引机日常操作与保养', 'OPERATION_MAINTENANCE', NULL,
    '<h2>日常要求</h2><p>结晶牵引机将铜液连续结晶并牵引形成铜坯。运行质量受冷却水、结晶器状态和牵引节拍共同影响。</p><p><strong>开机前</strong>确认冷却水畅通、结晶器安装可靠、牵引路径无异物；运行中关注出坯表面、牵引速度及水温变化。</p>',
    JSON_ARRAY('确认冷却水压力、流量和回水温度处于现场工艺卡范围。','检查结晶器、牵引轮及防护装置，确认无松动、渗漏和异物。','低速启动并观察出坯表面，确认无明显裂纹、夹渣或周期性振痕。','稳定运行后记录牵引速度、水温和异常现象；停机后清理结晶器周边铜屑和积水。')
  UNION ALL SELECT 'ROLL-01', '多道轧机组日常点检与保养', 'OPERATION_MAINTENANCE', NULL,
    '<h2>保养重点</h2><p>多道轧机组将粗铜坯连续轧制成约Φ8 mm铜杆。应重点控制轧辊、导卫、润滑冷却和传动系统状态。</p><ul><li>轧辊表面不得有剥落、粘铜和异常磨痕</li><li>导卫中心应与轧制中心一致</li><li>润滑冷却管路应畅通，无明显泄漏</li></ul>',
    JSON_ARRAY('交接班检查防护罩、急停和联锁状态。','检查轧辊、导卫及紧固件，发现松动或异常磨损时挂牌处理。','确认润滑冷却供给正常，再按现场规程低速试运转。','取样测量铜杆外径和表面质量，确认稳定后转入连续生产。')
  UNION ALL SELECT 'DRAW-02', '拉丝机出线张力偏高的常见原因', 'COMMON_FAULT', '出线张力持续升高、波动加大，可能伴随断丝频次上升或成品线径不稳定',
    '<h2>可能原因</h2><ul><li>拉丝模磨损、堵塞或润滑不足，导致变形阻力增加</li><li>放线、收线速度不同步或张力反馈漂移</li><li>铜杆表面氧化皮、划伤或来料直径波动</li><li>导轮卡滞、偏斜或轴承阻力增大</li></ul><p>若伴随异响、冒烟、连续断丝或安全防护异常，应立即按现场规程停机并通知维修人员。</p>',
    JSON_ARRAY('先核对张力显示与现场丝材状态，排除测量漂移。','检查润滑液供给、浓度、温度及过滤状态。','检查拉丝模、导轮和收放线路径是否存在磨损、卡滞或偏斜。','核对来料表面和直径，确认异常是否随卷材变化。','按现场权限完成调整或更换后低速试机，并复核张力与出线线径。')
  UNION ALL SELECT 'DRAW-03', '拉丝过程频繁断丝人工排查', 'TROUBLESHOOTING', '同一机台短时间内连续断丝，断点位置重复或断口形貌异常',
    '<h2>排查原则</h2><p>先隔离人员与旋转部件风险，再从来料、模具、润滑冷却、张力和收放线同步五个方面逐项排查。不得在设备运行时徒手触碰丝材、导轮或收线盘。</p>',
    JSON_ARRAY('停机、卸载张力并执行现场能源隔离要求，记录断丝发生道次和断口位置。','检查铜杆表面是否存在折叠、夹杂、划伤和局部氧化，必要时更换来料卷验证。','检查断丝道次拉丝模是否磨损、破裂、堵塞或安装偏心。','检查润滑液液位、浓度、温度、喷淋和过滤状态。','检查导轮转动、放线制动、收线排线及速度同步情况。','恢复防护后低速试机，连续观察张力、线速度和出线线径，确认稳定再恢复生产。')
  UNION ALL SELECT 'GAUGE-02', '在线测径仪读数漂移人工排查', 'TROUBLESHOOTING', '在线线径读数缓慢漂移、跳变或与离线量具复测结果偏差扩大',
    '<h2>判断说明</h2><p>测径偏差既可能来自产品波动，也可能来自镜头污染、安装偏移、振动、温漂或校准失效。应使用合格量具和标准件交叉验证。</p>',
    JSON_ARRAY('记录在线值、离线复测值、产品规格、机台速度和异常发生时间。','检查测量窗口是否有水雾、油污、铜粉或划伤，按说明书清洁。','检查测径仪支架、测量中心和线材路径是否偏移或振动。','使用在有效期内的标准件执行零点与跨度核验。','核对信号线、供电和通讯状态；仍异常时停用自动闭环并报修。')
  UNION ALL SELECT 'SMELT-FUR-01', '熔化炉温度分层异常人工排查', 'TROUBLESHOOTING', '炉膛上、中、下部温差明显扩大，单点温度突变或长期不随工况变化',
    '<h2>安全提示</h2><p>高温区域排查必须由具备资质的人员执行。未经许可不得打开炉门、拆卸热电偶或跨越联锁。</p><p>先判断是真实热工异常还是测量异常，再决定是否调整燃烧和投料节拍。</p>',
    JSON_ARRAY('核对三个测温点的趋势、变化时间和当前投料、出液工况。','检查异常点是否存在固定值、跳变、超量程或通讯中断特征。','在安全位置检查燃烧火焰、炉门密封和炉压表现。','核对热电偶接线、补偿导线和安装深度，必要时与便携测温结果比对。','确认真实温差异常后，由工艺负责人按受控工艺卡调整燃烧或物料节拍并持续观察。')
) x ON x.equipment_code = e.equipment_code
WHERE NOT EXISTS (SELECT 1 FROM p2_knowledge_article a WHERE a.title = x.title);
